mapper.update:
UPDATE public."CR_授業録音分塊情報"
   SET "処理状態"         = #{status},
       "転写セグメント数" = #{segmentCount},
       "更新日時"         = CURRENT_TIMESTAMP
 WHERE "授業記録ID" = #{recordId}
   AND "分塊連番"   = #{seq}

mapper.select:
SELECT 
  FROM public."CR_授業録音分塊情報"
 WHERE "授業記録ID" = #{recordId}
   AND "分塊連番"   = #{seq}

SELECT 
  FROM public."CR_授業録音分塊情報"
 WHERE "授業記録ID" = #{recordId}
   AND "分塊連番" > #{afterSeq}
 ORDER BY "分塊連番"

SELECT COALESCE(MAX("分塊連番"), 0)
  FROM public."CR_授業録音分塊情報"
 WHERE "授業記録ID" = #{recordId}

SELECT COUNT(*)
  FROM public."CR_授業録音分塊情報"
 WHERE "授業記録ID" = #{recordId}

SELECT COALESCE(SUM("バイト数"), 0)
  FROM public."CR_授業録音分塊情報"
 WHERE "授業記録ID" = #{recordId}

SELECT MAX("終了オフセット秒")
  FROM public."CR_授業録音分塊情報"
 WHERE "授業記録ID" = #{recordId}
